<?php
function adminTable(string $table,array $rows,array $schema,array $sample): void {
 $per=(int)($_GET['per_page']??10);if(!in_array($per,[10,20,50,100]))$per=10;[$items,$page,$pages,$total]=paginate($rows,$per);$ops=adminOps($table);$ordered=in_array($table,['banners','checklist','categories']);$list=$GLOBALS['adminCurrentList']??'/admin/'.$table;
 echo '<div class="admin-list-toolbar"><div class="row gap-8"><h2>검색 결과</h2><span>총 <strong class="text-brand">'.number_format($total).'</strong>건</span><span class="muted">'.$page.' / '.$pages.' 페이지</span></div><div class="row gap-8"><label class="sr-only" for="admin-sort">정렬</label><select class="select admin-select-small" id="admin-sort" data-list-option="sort">';foreach(['newest'=>$ordered?'순서순':'최신순','oldest'=>$ordered?'순서 역순':'오래된순','title'=>'제목·명칭순'] as $v=>$l)echo '<option value="'.$v.'"'.(($_GET['sort']??'newest')===$v?' selected':'').'>'.$l.'</option>';echo '</select><label class="sr-only" for="admin-per">페이지당 개수</label><select class="select admin-select-small" id="admin-per" data-list-option="per">';foreach([10,20,50,100] as $n)echo '<option value="'.$n.'"'.($per===$n?' selected':'').'>'.$n.'개씩 보기</option>';echo '</select><a class="button button--neutral" href="'.e(queryUrl(['export'=>'csv','page'=>null])).'">'.icon('download').' CSV 다운로드</a></div></div>';
 formStart('admin_bulk',['table'=>$table,'return'=>$list],'id="admin-bulk" data-bulk-form');
 if($ops){echo '<div class="admin-selection-bar"><span>현재 페이지 <strong data-selected-count aria-live="polite">0</strong>개 선택</span><label class="sr-only" for="bulk-op">일괄 작업</label><select class="select admin-select-small" id="bulk-op" name="op">';foreach($ops as $op=>$label)echo '<option value="'.$op.'">선택 '.$label.'</option>';echo '</select><label class="sr-only" for="bulk-reason">공통 처리 사유</label><input class="input admin-bulk-reason" name="reason" id="bulk-reason" placeholder="공통 처리 사유 · 보완·회원·취소 시 필수"><button type="submit" class="button button--neutral" data-bulk-submit disabled>일괄 처리</button><span class="help">전체 검색 결과 선택은 지원하지 않습니다.</span></div>';}
 if($ordered)echo '<div class="admin-order-toolbar"><span class="help">숫자를 수정한 후 현재 페이지 순서를 저장하세요.</span><button class="button button--outline" name="action" value="admin_reorder" data-save-order>노출 순서 저장</button></div>';
 if($items){$headers=array_keys(adminCells($table,$items[0]));echo '<div class="table-wrap" role="region" aria-label="'.e($schema['title']).' 검색 결과 표" tabindex="0"><table class="table table--operations"><caption class="sr-only">'.e($schema['title']).' · '.$total.'건 중 현재 페이지 '.$page.'</caption><thead><tr>';if($ops)echo '<th class="admin-check"><input type="checkbox" data-select-page aria-label="현재 페이지 전체 선택"></th>';foreach($headers as $h)echo '<th scope="col"'.(adminNumericColumn($h)?' class="number"':'').'>'.e($h).'</th>';if($ordered)echo '<th scope="col">순서 변경</th>';echo '<th scope="col" class="admin-row-action">관리</th></tr></thead><tbody>';
  foreach($items as $r){echo '<tr data-row-id="'.e($r['id']).'">';if($ops)echo '<td class="admin-check"><input type="checkbox" name="ids[]" value="'.e($r['id']).'" data-select-row aria-label="'.e(adminRowName($r)).' 선택"'.(adminSelectionBlock($table,$r)?' disabled title="'.e(adminSelectionBlock($table,$r)).'"':'').'></td>';foreach(adminCells($table,$r) as $h=>$cell)echo '<td'.(adminNumericColumn($h)?' class="number"':'').'>'.$cell.'</td>';if($ordered)echo '<td><input class="input admin-order-input" type="number" min="0" max="9999" name="orders['.e($r['id']).']" value="'.e($r['order']).'" aria-label="'.e(adminRowName($r)).' 순서"></td>';echo '<td class="admin-row-action">'.hidden('versions['.$r['id'].']',rowVersion($r)).'<a class="button button--neutral button--small" href="'.e(adminItemUrl($table,$r['id'],isset($schema['fields']),$list)).'">'.(isset($schema['fields'])?'수정':'상세').'</a></td></tr>';}
  echo '</tbody></table></div>';
 }else echo '<div class="admin-empty">'.icon('search').'<strong>검색 결과가 없습니다.</strong><p>검색어나 필터를 변경하거나 초기화해 주세요.</p><a class="button button--neutral" href="/admin/'.$table.'">검색 초기화</a></div>';
 echo '</form><div class="admin-pagination"><span class="muted">'.($total?(($page-1)*$per+1).'–'.min($page*$per,$total):'0').' / '.number_format($total).'건</span><nav aria-label="페이지 선택">';foreach(array_unique(array_merge([1],range(max(1,$page-2),min($pages,$page+2)),[$pages])) as $n)echo '<a class="button button--neutral" href="'.e(queryUrl(['page'=>$n])).'"'.($n===$page?' aria-current="page"':'').'>'.$n.'</a>';echo '</nav><span class="muted">현재 페이지 '.$per.'개씩</span></div>';
}
function adminNumericColumn(string $header): bool {return in_array($header,['순서','연결 콘텐츠','신청 / 정원','선정 / 정원','증감','사용 포인트','모집 인원','응모 수']);}
